    candidates uuid[];
    identifier uuid;
BEGIN
    IF TG_TABLE_SCHEMA <> 'public' OR TG_OP <> 'INSERT' THEN
        RAISE EXCEPTION '0163 return-stop insert fence only' USING ERRCODE='23514';
    END IF;
    IF TG_TABLE_NAME = 'stock_loss_return_stops' THEN
        candidates := ARRAY[NEW.root_disposition_id];
    ELSIF TG_TABLE_NAME = 'stock_operation_outbounds' THEN
        SELECT array_agg(id ORDER BY id) INTO candidates
        FROM public.stock_loss_dispositions WHERE return_operation_id=NEW.operation_id;
    ELSIF TG_TABLE_NAME = 'stock_operation_outbound_lines' THEN
        -- Follow both ends, including an intentionally cross-linked line.
        SELECT array_agg(DISTINCT d.id ORDER BY d.id) INTO candidates
        FROM public.stock_loss_dispositions d
        WHERE d.return_operation_id IN (
            SELECT operation_id FROM public.stock_operation_lines WHERE id=NEW.operation_line_id
            UNION SELECT operation_id FROM public.stock_operation_outbounds WHERE id=NEW.outbound_id);
    ELSE
        RAISE EXCEPTION '0163 unsupported return-stop fence table' USING ERRCODE='23514';
    END IF;
    FOREACH identifier IN ARRAY COALESCE(candidates, ARRAY[]::uuid[]) LOOP
        -- The competing insert must acquire the same immutable origin row.
        -- Keep the subsequent SELECT as a separate VOLATILE SQL statement so
        -- READ COMMITTED observes a winner that committed during this wait.
        SELECT * INTO root FROM public.stock_loss_dispositions WHERE id=identifier FOR UPDATE;
        IF root.id IS NULL OR root.disposition IS DISTINCT FROM 'return_to_region'
            OR root.return_operation_id IS NULL THEN
            RAISE EXCEPTION '0163 exact original loss return required' USING ERRCODE='23514';
        END IF;
        IF TG_TABLE_NAME = 'stock_loss_return_stops' THEN
            IF NEW.return_operation_id IS DISTINCT FROM root.return_operation_id
                OR NOT EXISTS(SELECT 1 FROM public.stock_operation_lines
                    WHERE id=NEW.return_line_id AND operation_id=root.return_operation_id)
                OR EXISTS(SELECT 1 FROM public.stock_loss_return_stops
                    WHERE root_disposition_id=root.id OR return_operation_id=root.return_operation_id)
                OR EXISTS(SELECT 1 FROM public.stock_operation_cancellations
                    WHERE operation_id=root.return_operation_id)
                OR EXISTS(SELECT 1 FROM public.stock_operation_outbounds
                    WHERE operation_id=root.return_operation_id)
                OR EXISTS(SELECT 1 FROM public.stock_operation_outbound_lines departure
                    JOIN public.stock_operation_lines line ON line.id=departure.operation_line_id
                    WHERE line.operation_id=root.return_operation_id)
                OR EXISTS(SELECT 1 FROM public.stock_operation_shipments
                    WHERE operation_id=root.return_operation_id) THEN
                RAISE EXCEPTION '0163 whole unshipped return required for stop' USING ERRCODE='23514';
            END IF;
        ELSIF EXISTS(SELECT 1 FROM public.stock_loss_return_stops
                WHERE root_disposition_id=root.id OR return_operation_id=root.return_operation_id) THEN
            RAISE EXCEPTION '0163 stopped loss return cannot depart' USING ERRCODE='23514';
        END IF;
    END LOOP;
    RETURN NEW;
END;

