DECLARE identifier uuid; aggregate text; aggregate_id text; kind text; body jsonb;
BEGIN
    IF TG_TABLE_SCHEMA<>'public' OR TG_OP<>'INSERT' THEN
        RAISE EXCEPTION '0163 stop insert guard only' USING ERRCODE='23514';
    END IF;
    IF TG_TABLE_NAME='stock_loss_return_stops' THEN
        identifier:=NEW.reversal_id;
    ELSE
        IF TG_TABLE_NAME='notification_events' THEN
            aggregate:=NEW.business_type; aggregate_id:=NEW.business_id; kind:=NEW.event_type; body:=NEW.payload_jsonb;
        ELSE
            aggregate:=NEW.aggregate_type; aggregate_id:=NEW.aggregate_id;
            IF TG_TABLE_NAME='audit_events' THEN kind:=NEW.action; body:=NEW.after_jsonb;
            ELSIF TG_TABLE_NAME='state_transition_events' THEN kind:=NEW.reason; body:=NEW.metadata_jsonb;
            ELSIF TG_TABLE_NAME='outbox_events' THEN kind:=NEW.event_type; body:=NEW.payload_jsonb;
            ELSE RAISE EXCEPTION '0163 unsupported event guard table' USING ERRCODE='23514'; END IF;
        END IF;
        IF kind='stock_loss.return_stopped' OR aggregate='stock_loss_return_stop'
            OR body->>'stop_scope'='whole_unshipped_return' THEN
            IF TG_TABLE_NAME='notification_events' OR kind IS DISTINCT FROM 'stock_loss.return_stopped'
                OR aggregate IS DISTINCT FROM 'stock_loss_return_stop' THEN
                RAISE EXCEPTION '0163 detached stop event type' USING ERRCODE='23514';
            END IF;
            SELECT reversal_id INTO identifier FROM public.stock_loss_return_stops WHERE id::text=aggregate_id;
            IF identifier IS NULL THEN
                RAISE EXCEPTION '0163 stop event needs exact fact' USING ERRCODE='23514';
            END IF;
        END IF;
    END IF;
    IF identifier IS NOT NULL THEN
        PERFORM public.rsc_check_loss_return_stop_0163(identifier);
        PERFORM public.rsc_check_loss_current_correction_0159(identifier,'reverse_loss');
    END IF;
    RETURN NULL;
END;

