DECLARE root public.stock_loss_dispositions%ROWTYPE;
    child public.stock_operation_orders%ROWTYPE;
    line public.stock_operation_lines%ROWTYPE;
    serials jsonb; lines jsonb; origin jsonb; fingerprint text;
BEGIN
    SELECT * INTO root FROM public.stock_loss_dispositions WHERE id=checked_root;
    IF root.id IS NULL OR root.disposition IS DISTINCT FROM 'return_to_region'
        OR root.return_operation_id IS NULL THEN
        RAISE EXCEPTION '0163 exact return boundary root required' USING ERRCODE='23514';
    END IF;
    PERFORM public.rsc_check_loss_return_0152(root.id,false);
    SELECT * INTO child FROM public.stock_operation_orders WHERE id=root.return_operation_id;
    SELECT * INTO line FROM public.stock_operation_lines WHERE operation_id=child.id;
    IF child.id IS NULL OR line.id IS NULL
        OR (SELECT count(*) FROM public.stock_operation_lines WHERE operation_id=child.id)<>1
        OR line.quantity IS DISTINCT FROM root.quantity
        OR EXISTS(SELECT 1 FROM public.stock_operation_cancellations WHERE operation_id=child.id)
        OR EXISTS(SELECT 1 FROM public.stock_operation_outbounds WHERE operation_id=child.id)
        OR EXISTS(SELECT 1 FROM public.stock_operation_outbound_lines departure
            JOIN public.stock_operation_lines original ON original.id=departure.operation_line_id
            WHERE original.operation_id=child.id)
        OR EXISTS(SELECT 1 FROM public.stock_operation_shipments WHERE operation_id=child.id) THEN
        RAISE EXCEPTION '0163 complete unshipped return boundary required' USING ERRCODE='23514';
    END IF;
    SELECT COALESCE(jsonb_agg(serial_id::text ORDER BY serial_id::text),'[]'::jsonb)
        INTO serials FROM public.stock_operation_serials WHERE line_id=line.id;
    IF serials IS DISTINCT FROM root.plan_jsonb->'serial_ids' THEN
        RAISE EXCEPTION '0163 exact original return serials required' USING ERRCODE='23514';
    END IF;
    lines:=jsonb_build_array(jsonb_build_object('operation_line_id',line.id::text,
        'quantity',to_char(line.quantity,'FM999999999999990.000'),'serial_ids',serials));
    origin:=jsonb_build_object('schema_version','unshipped_return_boundary/1',
        'root_disposition_id',root.id::text,'root_request_hash',root.request_hash,
        'root_plan_hash',root.plan_hash,'return_operation_id',child.id::text,
        'return_request_hash',child.request_hash,'return_plan_hash',child.plan_hash,'lines',lines);
    fingerprint:=encode(sha256(convert_to(public.rsc_canonical_reconciliation_json_0026(origin),'UTF8')),'hex');
    RETURN jsonb_build_object('disposition_id',root.id::text,'operation_id',child.id::text,
        'cancellations','[]'::jsonb,'outbounds','[]'::jsonb,'shipments','[]'::jsonb,
        'receipts','[]'::jsonb,'inbounds','[]'::jsonb,'evidence_fingerprint',fingerprint,'lines',lines);
END;

