DECLARE inverse public.stock_loss_disposition_reversals%ROWTYPE; root public.stock_loss_dispositions%ROWTYPE;
    parent public.stock_operation_orders%ROWTYPE; tx public.inventory_transactions%ROWTYPE;
    original_tx public.inventory_transactions%ROWTYPE; source public.stock_accounts%ROWTYPE; target public.stock_accounts%ROWTYPE;
    custody public.custody_assignments%ROWTYPE; policy public.material_inventory_policies%ROWTYPE;
    observed bigint; cutoff bigint; source_amount numeric; target_amount numeric; source_version bigint; target_version bigint;
    serial_ids jsonb; serial_basis jsonb:='[]'::jsonb; holds jsonb; share jsonb; recorded jsonb; fingerprint jsonb;
    expected jsonb; command jsonb; identifier uuid; current_sn record; prior_sn record;
    effective_from_text text; effective_to_text text;
    selected_execution uuid; selected_transaction uuid; selected_movement uuid;
    selected_target uuid; selected_kind text; selected_quantity numeric;
    correction public.stock_loss_correction_executions%ROWTYPE; return_boundary jsonb:=NULL;
BEGIN
    SELECT * INTO inverse FROM public.stock_loss_disposition_reversals WHERE id=checked_inverse;
    SELECT * INTO root FROM public.stock_loss_dispositions WHERE id=inverse.root_disposition_id;
    IF inverse.id IS NULL OR root.id IS NULL THEN
        RAISE EXCEPTION 'later inverse retained root required' USING ERRCODE='23514'; END IF;
    IF inverse.reversed_correction_id IS NULL THEN
        selected_execution:=root.id; selected_transaction:=root.posting_transaction_id;
        selected_movement:=root.posting_movement_id; selected_target:=root.target_account_id;
        selected_kind:=root.disposition; selected_quantity:=root.quantity;
    ELSE
        SELECT * INTO correction FROM public.stock_loss_correction_executions WHERE id=inverse.reversed_correction_id;
        IF correction.id IS NULL OR correction.root_disposition_id IS DISTINCT FROM root.id THEN
            RAISE EXCEPTION 'later inverse exact selected correction required' USING ERRCODE='23514'; END IF;
        selected_execution:=correction.id; selected_transaction:=correction.posting_transaction_id;
        selected_movement:=correction.posting_movement_id; selected_target:=correction.target_account_id;
        selected_kind:=correction.disposition; selected_quantity:=correction.quantity;
    END IF;
    IF selected_kind NOT IN ('restore_available','convert_used','convert_damaged','return_to_region')
       OR (selected_kind='return_to_region' AND inverse.reversed_correction_id IS NOT NULL)
       OR selected_transaction IS NULL OR selected_movement IS NULL OR selected_target IS NULL
       OR selected_quantity IS DISTINCT FROM root.quantity OR inverse.quantity IS DISTINCT FROM root.quantity
       OR inverse.original_transaction_id IS DISTINCT FROM selected_transaction
       OR inverse.original_movement_id IS DISTINCT FROM selected_movement THEN
        RAISE EXCEPTION 'later inverse exact account posting required' USING ERRCODE='23514'; END IF;
    IF selected_kind='return_to_region' THEN
        return_boundary:=public.rsc_check_loss_return_stop_0163(inverse.id);
    END IF;
    PERFORM public.rsc_check_loss_chain_events_0159(root.id);
    SELECT COALESCE(max(ledger_cursor),0) INTO observed FROM public.inventory_transactions;
    SELECT * INTO parent FROM public.stock_operation_orders WHERE id=root.operation_id;
    SELECT * INTO tx FROM public.inventory_transactions WHERE id=inverse.posting_transaction_id;
    SELECT * INTO original_tx FROM public.inventory_transactions WHERE id=selected_transaction;
    SELECT * INTO source FROM public.stock_accounts WHERE id=inverse.source_account_id;
    SELECT * INTO target FROM public.stock_accounts WHERE id=inverse.target_account_id;
    cutoff:=tx.ledger_cursor-1;
    IF source.id IS NULL OR target.id IS NULL OR target.availability_bucket IS DISTINCT FROM 'frozen'
       OR source.availability_bucket IS DISTINCT FROM (CASE WHEN selected_kind='return_to_region' THEN 'return_pending' ELSE 'available' END) OR source.id IS DISTINCT FROM selected_target
       OR target.id IS DISTINCT FROM root.source_account_id OR source.id=target.id
       OR source.owner_org_id IS DISTINCT FROM target.owner_org_id OR source.location_id IS DISTINCT FROM target.location_id
       OR source.custodian_person_id IS DISTINCT FROM target.custodian_person_id
       OR target.custodian_person_id IS DISTINCT FROM parent.requester_id
       OR source.material_id IS DISTINCT FROM target.material_id OR source.lot_id IS DISTINCT FROM target.lot_id
       OR original_tx.ledger_cursor>cutoff THEN
        RAISE EXCEPTION '0159 exact historical inverse accounts required' USING ERRCODE='23514'; END IF;
    SELECT * INTO custody FROM public.custody_assignments WHERE location_id=target.location_id
        AND valid_from<=inverse.created_at AND (valid_to IS NULL OR valid_to>inverse.created_at);
    IF custody.id IS DISTINCT FROM inverse.custody_assignment_id OR custody.custodian_person_id IS DISTINCT FROM parent.requester_id
       OR (SELECT count(*) FROM public.custody_assignments WHERE location_id=target.location_id
            AND valid_from<=inverse.created_at AND (valid_to IS NULL OR valid_to>inverse.created_at))<>1 THEN
        RAISE EXCEPTION '0159 unique historical inverse custody required' USING ERRCODE='23514'; END IF;
    SELECT COALESCE(sum(CASE WHEN m.to_account_id=source.id THEN m.quantity ELSE -m.quantity END),0),count(DISTINCT t.id)
        INTO source_amount,source_version FROM public.inventory_movements m JOIN public.inventory_transactions t ON t.id=m.transaction_id
        WHERE t.status='posted' AND t.ledger_cursor<=cutoff AND source.id IN (m.from_account_id,m.to_account_id);
    SELECT COALESCE(sum(CASE WHEN m.to_account_id=target.id THEN m.quantity ELSE -m.quantity END),0),count(DISTINCT t.id)
        INTO target_amount,target_version FROM public.inventory_movements m JOIN public.inventory_transactions t ON t.id=m.transaction_id
        WHERE t.status='posted' AND t.ledger_cursor<=cutoff AND target.id IN (m.from_account_id,m.to_account_id);
    IF source_amount<inverse.quantity OR target_amount<0 THEN
        RAISE EXCEPTION '0159 sufficient historical inverse balances required' USING ERRCODE='23514'; END IF;
    holds:=public.rsc_loss_hold_projection_0159(target.id,cutoff);
    SELECT value INTO share FROM jsonb_array_elements(holds->'lines') WHERE value->>'line_id'=root.line_id::text;
    IF share IS NULL OR share->>'active_execution_id' IS DISTINCT FROM selected_execution::text
       OR share->'pending_reversal_id' IS DISTINCT FROM 'null'::jsonb OR share->>'frozen_quantity' IS DISTINCT FROM '0.000' THEN
        RAISE EXCEPTION '0159 exact pre-inverse released share required' USING ERRCODE='23514'; END IF;
    SELECT COALESCE(jsonb_agg(serial_id::text ORDER BY serial_id::text),'[]'::jsonb) INTO serial_ids
        FROM public.stock_operation_serials WHERE line_id=root.line_id;
    FOR identifier IN SELECT value::uuid FROM jsonb_array_elements_text(serial_ids) LOOP
        SELECT m.id,m.to_account_id,m.external_boundary_code,t.ledger_cursor INTO current_sn
            FROM public.inventory_movement_serials s JOIN public.inventory_movements m ON m.id=s.movement_id
            JOIN public.inventory_transactions t ON t.id=m.transaction_id WHERE s.serial_id=identifier
                AND s.transaction_id=t.id AND t.status='posted' AND t.ledger_cursor<=cutoff
            ORDER BY t.ledger_cursor DESC,m.line_no DESC LIMIT 1;
        SELECT m.id,m.to_account_id,m.external_boundary_code,t.ledger_cursor INTO prior_sn
            FROM public.inventory_movement_serials s JOIN public.inventory_movements m ON m.id=s.movement_id
            JOIN public.inventory_transactions t ON t.id=m.transaction_id WHERE s.serial_id=identifier
                AND s.transaction_id=t.id AND t.status='posted' AND t.ledger_cursor<original_tx.ledger_cursor
            ORDER BY t.ledger_cursor DESC,m.line_no DESC LIMIT 1;
        IF current_sn.id IS DISTINCT FROM selected_movement OR current_sn.to_account_id IS DISTINCT FROM source.id
           OR prior_sn.id IS NULL OR prior_sn.to_account_id IS DISTINCT FROM target.id
           OR current_sn.external_boundary_code IS NOT NULL OR prior_sn.external_boundary_code IS NOT NULL
           OR NOT EXISTS(SELECT 1 FROM public.inventory_serials WHERE id=identifier AND material_id=source.material_id
                AND lot_id IS NOT DISTINCT FROM source.lot_id) THEN
            RAISE EXCEPTION '0159 exact active inverse serial lineage required' USING ERRCODE='23514'; END IF;
        serial_basis:=serial_basis||jsonb_build_array(jsonb_build_object('serial_id',identifier::text,
            'original_movement_id',selected_movement::text,'lifecycle_before','active','lifecycle_after','active',
            'previous_movement_id',prior_sn.id::text,'previous_ledger_cursor',prior_sn.ledger_cursor));
    END LOOP;
    SELECT * INTO policy FROM public.material_inventory_policies WHERE material_id=target.material_id
        AND effective_from<=inverse.created_at AND (effective_to IS NULL OR effective_to>inverse.created_at);
    IF policy.id IS NULL OR (SELECT count(*) FROM public.material_inventory_policies WHERE material_id=target.material_id
            AND effective_from<=inverse.created_at AND (effective_to IS NULL OR effective_to>inverse.created_at))<>1
