        END IF;
        PERFORM public.rsc_check_loss_upstream_history_0159(root.id);
        -- Prove the actual predecessor before its inverse, in ledger order.
        -- Chain projection independently rejects forks, cycles and disconnected edges.
        FOR edge IN SELECT x.id,x.kind FROM (
            SELECT id,posting_transaction_id,'inverse'::text AS kind
                FROM public.stock_loss_disposition_reversals WHERE root_disposition_id=root.id
